ALTER TABLE public.orders DROP CONSTRAINT orders_status_check;
ALTER TABLE public.orders ADD CONSTRAINT orders_status_check CHECK (status = ANY (ARRAY['pending'::text, 'awaiting_payment'::text, 'paid'::text, 'accepted'::text, 'preparing'::text, 'ready'::text, 'delivering'::text, 'delivered'::text, 'cancelled'::text]));